using System.Globalization;
using System.Text.RegularExpressions;
using MSFSBlindAssist.Aircraft.BBS757;

namespace MSFSBlindAssist.Tests;

/// <summary>
/// The BlueBird 757-200 control map loads from its embedded resource and keeps the shape the
/// writers and the panels rely on. The map is generated by <c>tools/b757-gen</c>, so these tests
/// pin what a regeneration must never lose: a way to write every control, one spoken name per
/// panel row, and the JSON's snake_case names reaching the model.
/// </summary>
public class Bbs757ControlMapTests
{
    private static readonly Bbs757ControlMap Map = Bbs757ControlMap.Load();

    private static Bbs757Control Find(string node) => Assert.Single(Map.Controls, c => c.Node == node);

    [Fact]
    public void Load_finds_the_battery()
    {
        Assert.True(Map.Controls.Count > 200, $"only {Map.Controls.Count} controls loaded");

        Bbs757Control battery = Find("B757_OVHD_BATTERY_BUTTON");

        Assert.Equal(Bbs757Kinds.Toggle, battery.Kind);
        Assert.Equal("Battery", battery.Label);
        Assert.Equal(new[] { "Off", "On" }, battery.Positions.Select(p => p.Label));
        Assert.Contains(">L:B757_OVHD_BATTERY_BUTTON", battery.Press);
    }

    [Fact]
    public void Positions_deserialize_from_value_and_label()
    {
        Bbs757Control battery = Find("B757_OVHD_BATTERY_BUTTON");

        Assert.Equal(new Bbs757Position(0, "Off"), battery.Positions[0]);
        Assert.Equal(new Bbs757Position(1, "On"), battery.Positions[1]);
    }

    [Fact]
    public void Snake_case_fields_reach_the_model()
    {
        Bbs757Control apu = Find("B757_OVHD_APU_SWITCH");

        Assert.Equal("Overhead", apu.Section);
        Assert.Equal("APU", apu.Panel);
        Assert.Equal("B757_OVHD_APU_SWITCH", apu.StateVar);
        Assert.False(string.IsNullOrWhiteSpace(apu.Cw));
        Assert.False(string.IsNullOrWhiteSpace(apu.Ccw));

        Bbs757Control held = Map.Controls.First(c => c.Kind == Bbs757Kinds.Held);
        Assert.True(held.HoldMs > 0, $"{held.Node} has no hold time");
        Assert.False(string.IsNullOrWhiteSpace(held.Release), $"{held.Node} has no release code");
    }

    [Fact]
    public void Every_control_has_a_writer()
    {
        // A switch with no click code at all is written by setting its state var (the vendor drives
        // it through other means); every other control needs its own press or its cw and ccw.
        var unwritable = Map.Controls.Where(c =>
            string.IsNullOrWhiteSpace(c.Press)
            && !(!string.IsNullOrWhiteSpace(c.Cw) && !string.IsNullOrWhiteSpace(c.Ccw))
            && !(c.Kind == Bbs757Kinds.Switch && !string.IsNullOrWhiteSpace(c.StateVar)))
            .Select(c => c.Node).ToList();

        Assert.True(unwritable.Count == 0, "no way to write: " + string.Join(", ", unwritable));
    }

    [Fact]
    public void Every_kind_is_one_of_the_six()
    {
        var known = new[]
        {
            Bbs757Kinds.Button, Bbs757Kinds.Toggle, Bbs757Kinds.Switch,
            Bbs757Kinds.Guard, Bbs757Kinds.Select, Bbs757Kinds.Held,
        };

        Assert.All(Map.Controls, c => Assert.Contains(c.Kind, known));
    }

    [Fact]
    public void Labels_are_unique_per_panel()
    {
        // VAR-1: two rows of one panel must never share a spoken name.
        var clashes = Map.Controls
            .GroupBy(c => (c.Section, c.Panel, c.Label))
            .Where(g => g.Count() > 1)
            .Select(g => $"{g.Key.Section} / {g.Key.Panel} / {g.Key.Label}: " + string.Join(", ", g.Select(c => c.Node)))
            .ToList();

        Assert.True(clashes.Count == 0, string.Join("\n", clashes));
    }

    [Fact]
    public void Status_rows_carry_their_positions_and_announce_flag()
    {
        Assert.NotEmpty(Map.Status);

        Bbs757StatusRow apu = Assert.Single(Map.Status, s => s.Key == "B757_APU_STATE");

        Assert.Equal("Status", apu.Panel);
        Assert.Equal("APU", apu.Label);
        Assert.True(apu.Announce);
        Assert.Equal(new Bbs757Position(2, "Running"), apu.Positions[2]);
    }

    // ---- Task 10a: the control stand, taken in by node from two excluded vendor banners ----

    private static (double Value, string Label)[] Pairs(Bbs757Control c) =>
        c.Positions.Select(p => (p.Value, p.Label)).ToArray();

    [Fact]
    public void The_control_stand_holds_the_six_controls_taken_in_by_node_and_the_flap_lever()
    {
        var stand = Map.Controls.Where(c => c.Panel == "Control stand").ToList();

        Assert.All(stand, c => Assert.Equal("Pedestal", c.Section));
        // The six taken in from the excluded banners by node, and the flap lever (plan 02 task 7: a lever the rules leave
        // out, built from the generator's levers key; its banner is one of the excluded ones).
        Assert.Equal(
            new[]
            {
                "B757_AT_DISC_1", "BBS757_PEDESTAL_Park_Brake_Lever", "BBS757_SPOILERARMED_CLICK",
                "BBS757_SPOILERDOWN_CLICK", "BBS757_SPOILERUP_CLICK", "BBS757_lever_flaps", "ENGINE_Switch_ATDisc_1",
            },
            stand.Select(c => c.Node).OrderBy(n => n, StringComparer.Ordinal));
        // The banners stay excluded: the right-hand TO/GA and A/T disconnect and the speed brake lever
        // sit under them and are not in the map.
        Assert.DoesNotContain(Map.Controls, c => c.Node is "ENGINE_Switch_ATDisc_2" or "B757_AT_DISC_2"
            or "BBS757_lever_speed_brake" or "lever_speed_brake");
    }

    [Fact]
    public void The_parking_brake_is_a_toggle_on_its_own_var_named_Released_and_Set()
    {
        Bbs757Control brake = Find("BBS757_PEDESTAL_Park_Brake_Lever");

        Assert.Equal("Parking Brake", brake.Label);
        Assert.Equal(("Pedestal", "Control stand"), (brake.Section, brake.Panel));
        Assert.Equal(Bbs757Kinds.Toggle, brake.Kind);
        Assert.Equal("B757_FC_PARK_BRAKE", brake.StateVar);
        Assert.Equal(new[] { (0d, "Released"), (1d, "Set") }, Pairs(brake));
        Assert.Contains(">L:B757_FC_PARK_BRAKE", brake.Press);
    }

    [Theory]
    [InlineData("BBS757_SPOILERDOWN_CLICK", "Speedbrake Down", "0 (>L:B757_FC_SPOILER_LEVER, number)")]
    [InlineData("BBS757_SPOILERARMED_CLICK", "Speedbrake Armed", "10 (>L:B757_FC_SPOILER_LEVER, number)")]
    [InlineData("BBS757_SPOILERUP_CLICK", "Speedbrake Up", "100 (>L:B757_FC_SPOILER_LEVER, number)")]
    public void Each_speedbrake_click_spot_is_a_button_that_sets_the_lever_var(string node, string label, string press)
    {
        Bbs757Control c = Find(node);

        Assert.Equal(label, c.Label);
        Assert.Equal(("Pedestal", "Control stand"), (c.Section, c.Panel));
        Assert.Equal(Bbs757Kinds.Button, c.Kind);
        Assert.Equal(press, c.Press);   // the vendor's code, verbatim
        Assert.Empty(c.Positions);
    }

    [Fact]
    public void TO_GA_and_the_A_T_disconnect_replay_the_vendors_click_code()
    {
        Bbs757Control toga = Find("ENGINE_Switch_ATDisc_1");

        Assert.Equal("TO/GA", toga.Label);
        Assert.Equal(("Pedestal", "Control stand"), (toga.Section, toga.Panel));
        Assert.Equal(Bbs757Kinds.Button, toga.Kind);
        Assert.Equal("1 (>L:GO_AROUND_PADDLE1, bool) 1 (>K:AUTO_THROTTLE_TO_GA)", toga.Press);
        Assert.Equal("0 (>L:GO_AROUND_PADDLE1, bool)", toga.Release);

        Bbs757Control disconnect = Find("B757_AT_DISC_1");

        Assert.Equal("A/T Disconnect", disconnect.Label);
        Assert.Equal(("Pedestal", "Control stand"), (disconnect.Section, disconnect.Panel));
        Assert.Equal(Bbs757Kinds.Button, disconnect.Kind);
        Assert.Contains(">L:B757_AT_DISC_1", disconnect.Press);
    }

    [Fact]
    public void The_two_hold_buttons_are_labelled_by_what_they_hold()
    {
        Bbs757Control hdg = Find("B757_MCP_HOLD_1_BUTTON");
        Bbs757Control alt = Find("B757_MCP_HOLD_2_BUTTON");

        Assert.Equal("HDG HOLD", hdg.Label);
        Assert.Equal("ALT HOLD", alt.Label);
        Assert.All(new[] { hdg, alt }, c => Assert.Equal(("Glareshield", "MCP"), (c.Section, c.Panel)));
    }

    [Fact]
    public void The_ignition_selector_is_named_ignition_beside_the_two_start_selectors_on_the_pedestal()
    {
        // The nodes say B757_OVHD_, which the generator would put in the Overhead; the curation moves all three
        // to the Pedestal's Engines panel (task 11d, ruling R37).
        Bbs757Control ignition = Find("B757_OVHD_ENG_START_SWITCH");

        Assert.Equal("Ignition", ignition.Label);
        Assert.All(new[] { ignition, Find("B757_OVHD_L_ENG_START_SWITCH"), Find("B757_OVHD_R_ENG_START_SWITCH") },
            c => Assert.Equal(("Pedestal", "Engines"), (c.Section, c.Panel)));
        Assert.Equal(new[] { "L ENG Start", "R ENG Start" },
            new[] { "B757_OVHD_L_ENG_START_SWITCH", "B757_OVHD_R_ENG_START_SWITCH" }.Select(n => Find(n).Label));
    }

    [Fact]
    public void The_engines_panel_holds_the_start_selectors_and_the_four_fuel_control_switches_in_start_order()
    {
        var engines = Map.Controls.Where(c => c.Section == "Pedestal" && c.Panel == "Engines").ToList();

        Assert.Equal(
            new[]
            {
                "B757_OVHD_ENG_START_SWITCH", "B757_OVHD_L_ENG_START_SWITCH", "BBS_fuelcut_PW1",
                "B757_OVHD_R_ENG_START_SWITCH", "BBS_fuelcut_PW2", "BBS_fuelcut_RR1", "BBS_fuelcut_RR2",
            },
            engines.Select(c => c.Node));
        Assert.Equal(
            new[]
            {
                "Ignition", "L ENG Start", "L Fuel Control (PW)", "R ENG Start", "R Fuel Control (PW)",
                "L Fuel Control (RR)", "R Fuel Control (RR)",
            },
            engines.Select(c => c.Label));
    }

    [Fact]
    public void The_overhead_engine_start_panel_and_the_pedestal_fuel_control_panel_are_gone()
    {
        Assert.DoesNotContain(Map.Controls, c => c.Panel is "Engine start" or "Fuel control");
    }

    // ---- Task 11d: the panels in BlueBird's preflight-flow order, the most used controls first ----

    [Fact]
    public void The_sections_come_in_the_cockpit_order()
    {
        Assert.Equal(new[] { "Overhead", "Glareshield", "Forward panel", "Pedestal", "Other" },
            Map.Controls.Select(c => c.Section).Distinct());
    }

    [Theory]
    [InlineData("Overhead", "Electrical|APU|IRS|Engine control and yaw damper|Hydraulics|Overhead miscellaneous|Fuel|Anti-ice|Wipers|Exterior lights|Window heat|Passenger signs|Pressurization|Air conditioning and bleed|Cabin lights|IRS keypad|Switch guards|Flight deck door|CVR|SELCAL and cabin call|Ground service|Warning lights test")]
    [InlineData("Glareshield", "MCP|VOR/DME|Master warning and caution")]
    [InlineData("Forward panel", "Main panel switches|Landing gear|Captain EFIS|Yokes|Captain autoland status|Standby attitude indicator|Captain DDRMI|Captain chronometer|Oxygen|Cockpit miscellaneous|First officer EFIS|First officer autoland status|First officer DDRMI|First officer chronometer")]
    [InlineData("Pedestal", "Control stand|Engines|TCAS and transponder|EICAS control|Radio tuning panel 1|Audio panel 1|Fire protection|Stabilizer trim|Weather radar left|Radio tuning panel 2|Radio tuning panel 3|Audio panel 2|Weather radar right|Pedestal radio panels")]
    [InlineData("Other", "P61 panel")]
    public void The_panels_of_each_section_follow_the_manuals_preflight_flow(string section, string panels)
    {
        // The owner's order (ruling R37); every panel is listed, so none falls back to the alphabet.
        Assert.Equal(panels.Split('|'), Map.Controls.Where(c => c.Section == section).Select(c => c.Panel).Distinct());
    }

    [Theory]
    [InlineData("Electrical", "Battery|STBY Power|L Bus Tie|R Bus Tie|L Gen Cont|R Gen Cont|APU Gen|EXT PWR|L Util Bus|R Util Bus|L Gen Drive|R Gen Drive")]
    [InlineData("Hydraulics", "L ENG HYD Pumps|R ENG HYD Pumps|R ELEC Pump|C1 ELEC Pump|C2 ELEC Pump|L ELEC Pump")]
    [InlineData("Overhead miscellaneous", "Emergency Lights|Emergency Lights Guard")]
    [InlineData("Fuel", "L Pumps FWD|L Pumps Aft|R Pumps FWD|R Pumps Aft|C Pumps L|C Pumps R|Crossfeed FWD|Crossfeed Aft")]
    [InlineData("Exterior lights", "Anti-col Red Lights|Position Lights|Anti-col White Lights|Taxi Light|L Landing Light|R Landing Light|L Runway Turnoff|R Runway Turnoff|Wing Lights|Logo Lights")]
    [InlineData("Air conditioning and bleed", "L Pack Selector|R Pack Selector|Isolation|L ENG Bleed|APU Bleed|R ENG Bleed|Trim Air|L Recirc|R Recirc|L Pack|R Pack")]
    [InlineData("Passenger signs", "Seatbelts|No Smoking")]
    [InlineData("IRS", "IRS L|IRS C|IRS R")]
    // The two ELEC ENG Cont switches are on the RR cockpit only (no node in the PW one), so their labels say so.
    [InlineData("Engine control and yaw damper", "L Yaw Damper|R Yaw Damper|L ELEC ENG Cont (RR)|R ELEC ENG Cont (RR)")]
    [InlineData("MCP", "Captain F/D|F/O F/D|A/T Arm|THR|SPD|LNAV|VNAV|FLCH|HDG SEL|HDG HOLD|V/S|ALT HOLD|LOC|APP|CMD L|CMD C|CMD R|Autopilot Disengage Bar|IAS/MACH|ALT SEL Push|Speed Intervene|Bank Limit|BCRS 1")]
    [InlineData("Main panel switches", "Autobrake|Takeoff Check|TOGA|CLB|CON|CRZ|TMSP 1|TMSP 2|HDG Ref|Cancel|Recall")]
    // Plan 02 task 7: the flap lever right after Speedbrake Up, and the gear lever first on the Landing gear panel.
    [InlineData("Control stand", "Parking Brake|Speedbrake Armed|Speedbrake Down|Speedbrake Up|Flap Lever|TO/GA|A/T Disconnect")]
    [InlineData("Landing gear", "Gear Lever")]
    [InlineData("Engines", "Ignition|L ENG Start|L Fuel Control (PW)|R ENG Start|R Fuel Control (PW)|L Fuel Control (RR)|R Fuel Control (RR)")]
    [InlineData("TCAS and transponder", "TCAS Mode")]
    [InlineData("Captain EFIS", "ND Mode|ND Range")]
    [InlineData("First officer EFIS", "ND Mode|ND Range")]
    public void The_most_used_controls_lead_their_panel(string panel, string leading)
    {
        // The owner's lists (ruling R37), by the names the pilot hears.
        string[] expected = leading.Split('|');
        var labels = Map.Controls.Where(c => c.Panel == panel).Select(c => c.Label).ToList();

        Assert.Equal(expected, labels.Take(expected.Length));
    }

    [Theory]
    [InlineData("IRS", 3, "IRS Center Knob|IRS Large Knob")]
    [InlineData("TCAS and transponder", 1, "TCAS Xpndr|TCAS Ident|TCAS Mode Knob Test")]
    [InlineData("Captain EFIS", 2, "TFC|CTR|DH Reset|TERR|WXR|INOP|NAV AID|APRT|DATA|WPT")]
    [InlineData("First officer EFIS", 2, "TFC|CTR|DH Reset|TERR|WXR|INOP|NAV AID|APRT|DATA|WPT")]
    [InlineData("Landing gear", 1, "Gear Lock Override")]
    [InlineData("Main panel switches", 11, "L Flt Dir|L Flt Nav|L Foot Heaters|L Shoulder Heaters|L EFI|L IRS|L Airdata|L Brake Reserve|L Leading Edge|L Trailing Edge|L Flap Ovrd|G/S Inhibit|L Gear Ovrd|L Terr Ovrd|Altn Gear Guard|Altn Gear|Stdby EICAS|Alternate Flaps Selector|Flap Override Guard|Gear Override Guard|Terrain Override Guard|R Flt Dir|R Flt Nav|R Foot Heaters|R Shoulder Heaters|R EFI|R IRS|R Airdata")]
    public void The_controls_an_order_does_not_list_follow_in_cockpit_order(string panel, int listed, string rest)
    {
        // Cockpit order is the order of the vendor's cockpit file: the controls the order leaves out keep it.
        var after = Map.Controls.Where(c => c.Panel == panel).Select(c => c.Label).Skip(listed);

        Assert.Equal(rest.Split('|'), after);
    }

    [Fact]
    public void A_panel_name_is_in_one_section_only()
    {
        // The definition keys a panel's controls by its name, so two sections cannot share one.
        var shared = Map.Controls.GroupBy(c => c.Panel).Where(g => g.Select(c => c.Section).Distinct().Count() > 1)
            .Select(g => g.Key).ToList();

        Assert.True(shared.Count == 0, string.Join(", ", shared));
    }

    [Fact]
    public void The_chocks_are_a_silent_status_row()
    {
        // Ruling R31: L:BBS757_vis_chocks, measured 0 removed, 1 in place.
        var chocks = Assert.Single(Map.Status, s => s.Key == "BBS757_vis_chocks");

        Assert.Equal(("Status", "Chocks", false), (chocks.Panel, chocks.Label, chocks.Announce));
        Assert.Equal(new[] { new Bbs757Position(0, "Removed"), new Bbs757Position(1, "In place") }, chocks.Positions);
    }

