    [Theory]
    [InlineData("B757_MAIN_CHRONO_ET_SWITCH", "BBS_CHRONO_LEFT_SWITCH")]
    [InlineData("B757_MAIN_CHRONO_ET_SWITCH_FO", "BBS_CHRONO_LEFT_SWITCH_FO")]
    public void The_chronometer_ET_lever_keeps_no_click_code_and_names_RESET_at_3(string node, string stateVar)
    {
        Bbs757Control et = Find(node);

        // BlueBird's list says RESET is 3 with 2 unused; the cockpit's tooltip list says 2. The vendor's click code steps
        // down 3, 2, 1, 0 and up 0, 1, 3 (HOLD jumps straight to RESET): the step down from RESET lands on 2, which is no
        // position, so a pick made by stepping would be refused from there on. The map holds none of that code (ruling
        // R10): the app writes the state var. 3 is RESET and 2 is not a position.
        Assert.Equal(stateVar, et.StateVar);
        Assert.Equal(Bbs757Kinds.Switch, et.Kind);
        Assert.Equal("RESET", Assert.Single(et.Positions, p => p.Value == 3).Label);
        Assert.DoesNotContain(et.Positions, p => p.Value == 2);
        Assert.Null(et.Press);
        Assert.Null(et.Release);
        Assert.Null(et.Cw);
        Assert.Null(et.Ccw);
    }

    [Theory]
    [InlineData("B757_MAIN_CHRONO_ET_SWITCH", "BBS_CHRONO_LEFT_SWITCH")]
    [InlineData("B757_MAIN_CHRONO_ET_SWITCH_FO", "BBS_CHRONO_LEFT_SWITCH_FO")]
    public void Chronometer_ET_goes_straight_to_the_pick(string node, string stateVar)
    {
        Bbs757Control et = Find(node);

        IReadOnlyList<string> Writes(double? current, double target)
        {
            Bbs757WritePlan plan = Bbs757Write.ToPosition(et, current, target);
            Assert.Equal(Bbs757WriteOutcome.Writes, plan.Outcome);
            return plan.Calls;
        }

        // One absolute write of the picked value, whatever the lever reads. The vendor's code would have gone from RESET
        // down through 2, which is no position, and from HOLD up to RESET in one jump.
        Assert.Equal(new[] { $"1 (>L:{stateVar})" }, Writes(3, 1));   // RESET to HOLD
        Assert.Equal(new[] { $"3 (>L:{stateVar})" }, Writes(0, 3));   // RUN to RESET
        // A cockpit click can still leave the lever on 2, which is no position: the pick is written all the same.
        Assert.Equal(new[] { $"1 (>L:{stateVar})" }, Writes(2, 1));
        Assert.Equal(new[] { $"0 (>L:{stateVar})" }, Writes(2, 0));
        // The same writes under a comma-decimal culture (CI runs under en-US): the write is built with the invariant one.
        foreach (string culture in new[] { "de-DE", "sv-SE" })
        {
            Assert.Equal(new[] { $"1 (>L:{stateVar})" }, TestCulture.Run(culture, () => Writes(3, 1)));
            Assert.Equal(new[] { $"3 (>L:{stateVar})" }, TestCulture.Run(culture, () => Writes(2, 3)));
        }
        // A lever already at its pick is left alone, and 2, which is no position, is never picked.
        Assert.Equal(Bbs757WriteOutcome.AtPosition, Bbs757Write.ToPosition(et, 1, 1).Outcome);
        Assert.Equal(Bbs757WriteOutcome.Refused, Bbs757Write.ToPosition(et, 1, 2).Outcome);
    }

    [Fact]
    public void The_flight_deck_door_switch_keeps_no_click_code_and_goes_straight_to_the_pick()
    {
        const string stateVar = "B757_OVHD_FLT_DK_DOOR_SWITCH";
        Bbs757Control door = Find("B757_OVHD_FLT-DK-DOOR_SWITCH");

        // A spring-return lever. The vendor's cw and ccw write 2 and 0 whatever it reads (BBS_752_BASE_INTERIOR.xml:6698-6705),
        // so a step to Auto from either end landed on the other end. The map holds none of that code (ruling R12) and the
        // app writes the state var; BlueBird's own 1 Hz update (XML:6684-6687) still springs it back to Auto, as after a click.
        Assert.Equal(stateVar, door.StateVar);
        Assert.Equal(Bbs757Kinds.Switch, door.Kind);
        Assert.Equal("0=Unlocked|1=Auto|2=Deny", Spell(door));
        Assert.Null(door.Press);
        Assert.Null(door.Release);
        Assert.Null(door.Cw);
        Assert.Null(door.Ccw);

        IReadOnlyList<string> Writes(double? current, double target)
        {
            Bbs757WritePlan plan = Bbs757Write.ToPosition(door, current, target);
            Assert.Equal(Bbs757WriteOutcome.Writes, plan.Outcome);
            return plan.Calls;
        }

        // Every pick is one absolute write of the picked value. The two the vendor's code missed are Auto from either end.
        Assert.Equal(new[] { $"1 (>L:{stateVar})" }, Writes(2, 1));   // Deny to Auto
        Assert.Equal(new[] { $"1 (>L:{stateVar})" }, Writes(0, 1));   // Unlocked to Auto
        Assert.Equal(new[] { $"2 (>L:{stateVar})" }, Writes(1, 2));   // Auto to Deny
        Assert.Equal(new[] { $"0 (>L:{stateVar})" }, Writes(1, 0));   // Auto to Unlocked
        Assert.Equal(new[] { $"2 (>L:{stateVar})" }, Writes(0, 2));   // Unlocked to Deny
        Assert.Equal(new[] { $"0 (>L:{stateVar})" }, Writes(2, 0));   // Deny to Unlocked
        // The same writes under a comma-decimal culture (CI runs under en-US): the write is built with the invariant one.
        foreach (string culture in new[] { "de-DE", "sv-SE" })
        {
            Assert.Equal(new[] { $"1 (>L:{stateVar})" }, TestCulture.Run(culture, () => Writes(2, 1)));
            Assert.Equal(new[] { $"2 (>L:{stateVar})" }, TestCulture.Run(culture, () => Writes(0, 2)));
        }
        // A switch already at its pick is left alone, and a value that is no position is never picked.
        Assert.Equal(Bbs757WriteOutcome.AtPosition, Bbs757Write.ToPosition(door, 1, 1).Outcome);
        Assert.Equal(Bbs757WriteOutcome.Refused, Bbs757Write.ToPosition(door, 1, 3).Outcome);
    }

